const i=[{key:"cpu_percent",label:"CPU (% of node)",unit:"percent",build:e=>`fleetly_container_cpu_percent{app="${e}"}`},{key:"memory",label:"Memory working set (bytes)",unit:"bytes",build:e=>`fleetly_container_memory_working_set_bytes{app="${e}"}`},{key:"cpu_cores",label:"CPU (cores)",unit:"plain",build:e=>`fleetly_container_cpu_cores{app="${e}"}`}];function n(e,r){if(r==="bytes"){const t=Math.abs(e);return t>=1024**3?`${(e/1024**3).toFixed(1)} GiB`:t>=1024**2?`${(e/1024**2).toFixed(0)} MiB`:t>=1024?`${(e/1024).toFixed(0)} KiB`:`${e} B`}return r==="percent"?`${e>=100?e.toFixed(0):e.toFixed(1)}%`:Math.abs(e)>=100?e.toFixed(0):e.toFixed(2)}export{i as M,n as f};
